void require(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
float number(jass::Value value){return std::bit_cast<float>(value.bits);}
std::unique_ptr<ScriptSession> start(const wchar_t* root,const char* path,bool expansion=false,bool damageProbe=false){
    Archives archives(root);auto bytes=archives.readCandidates({path},ArchiveScope::Common);if(!bytes)throw std::runtime_error(std::string("Campaign map missing: ")+path);archives.mountMap(std::make_shared<const Bytes>(bytes->bytes),path);auto world=World::read(archives);auto info=world->data().info;MapStrings strings;if(auto wts=archives.readCandidates({"war3map.wts"},ArchiveScope::Map))strings=mapStrings(wts->bytes);auto program=jass::Program::read(archives);if(damageProbe){auto sources=program.sources();sources.push_back({"tower-probe.j",R"jass(
globals
    unit probeTower = null
    real probeDamage = 0.
    unit probeMortarA = null
    unit probeMortarB = null
    real probeMortarDamage = 0.
    unit probeShipKiller = null
    unit probeHumanGuardian = null
    unit probeHumanMalganis = null
    real probeHumanGuardianDamage = 0.
    real probeHumanMalganisDamage = 0.
    real probeHumanStructureDamage = 0.
    boolean probeHumanGuardianKill = false
    boolean probeHumanMalganisKill = false
    integer probeHumanStructureKills = 0
endglobals
function ProbeDamage takes nothing returns nothing
    if GetEventDamageSource() == probeTower then
        set probeDamage = probeDamage + GetEventDamage()
    endif
endfunction
function ProbeShipDamage takes nothing returns nothing
    if GetEventDamageSource() == probeMortarA or GetEventDamageSource() == probeMortarB then
        set probeMortarDamage = probeMortarDamage + GetEventDamage()
    endif
endfunction
function ProbeShipDeath takes nothing returns nothing
    set probeShipKiller = GetKillingUnit()
endfunction
function ProbeShip takes unit first, unit second, unit target returns nothing
    local trigger damage = CreateTrigger()
    local trigger death = CreateTrigger()
    set probeMortarA = first
    set probeMortarB = second
    set probeMortarDamage = 0.
    set probeShipKiller = null
    call TriggerRegisterUnitEvent(damage, target, EVENT_UNIT_DAMAGED)
    call TriggerAddAction(damage, function ProbeShipDamage)
    call TriggerRegisterUnitEvent(death, target, EVENT_UNIT_DEATH)
    call TriggerAddAction(death, function ProbeShipDeath)
endfunction
function ProbeHumanDamage takes nothing returns nothing
    if GetEventDamageSource() != null and GetOwningPlayer(GetEventDamageSource()) == Player(1) then
        if GetTriggerUnit() == probeHumanGuardian then
            set probeHumanGuardianDamage = probeHumanGuardianDamage + GetEventDamage()
        elseif GetTriggerUnit() == probeHumanMalganis then
            set probeHumanMalganisDamage = probeHumanMalganisDamage + GetEventDamage()
        else
            set probeHumanStructureDamage = probeHumanStructureDamage + GetEventDamage()
        endif
    endif
endfunction
function ProbeHumanDeath takes nothing returns nothing
    if GetKillingUnit() != null and GetOwningPlayer(GetKillingUnit()) == Player(1) then
        if GetTriggerUnit() == probeHumanGuardian then
            set probeHumanGuardianKill = true
        elseif GetTriggerUnit() == probeHumanMalganis then
            set probeHumanMalganisKill = true
        else
            set probeHumanStructureKills = probeHumanStructureKills + 1
        endif
    endif
endfunction
function ProbeHumanTarget takes unit target returns nothing
    local trigger damage = CreateTrigger()
    local trigger death = CreateTrigger()
    call TriggerRegisterUnitEvent(damage, target, EVENT_UNIT_DAMAGED)
    call TriggerAddAction(damage, function ProbeHumanDamage)
    call TriggerRegisterUnitEvent(death, target, EVENT_UNIT_DEATH)
    call TriggerAddAction(death, function ProbeHumanDeath)
endfunction
function ProbeHumanGuardian takes unit target returns nothing
    set probeHumanGuardian = target
    call ProbeHumanTarget(target)
endfunction
function ProbeHumanMalganis takes unit target returns nothing
    set probeHumanMalganis = target
    call ProbeHumanTarget(target)
endfunction
function ProbeTarget takes unit tower, unit target returns nothing
    local trigger t = CreateTrigger()
    set probeTower = tower
    call TriggerRegisterUnitEvent(t, target, EVENT_UNIT_DAMAGED)
    call TriggerAddAction(t, function ProbeDamage)
endfunction
)jass","tower damage probe"});program=jass::Program::parse(std::move(sources));}auto session=std::make_unique<ScriptSession>(jass::Module::compile(std::move(program)),info,std::move(strings));session->campaignContext(expansion,1);session->attachWorld(std::move(world));session->audioSimulationClock();session->audioMuted(true);session->configure();PlayerSetup setup(info,session->config());session->applySetup(setup);session->startMain();return session;
}
